(() => {
const C={g:'#c7f36b',c:'#79dce8',o:'#ffab78',m:'#92a1ae'},fmt=(n,d=3)=>Number(n).toFixed(d);
const range=(id,label,min,max,val,step=.01)=>`<label class="range-control"><span>${label}<output id="${id}-v">${val}</output></span><input type="range" id="${id}" min="${min}" max="${max}" step="${step}" value="${val}"></label>`;
const stat=(name,n,color=C.c)=>`<div class="viz-stat"><span>${name}</span><strong style="color:${color}">${n}</strong></div>`;
const svg=(str,label)=>`<svg viewBox="0 0 600 300" role="img" aria-label="${label}">${str}</svg>`;
const body=(controls,instruction)=>`<div class="viz-stage"></div><div class="viz-stats"></div><div class="viz-controls">${controls}</div><p class="viz-instruction">${instruction}</p>`;
function mount(root,html,update){root.innerHTML=html;root.querySelectorAll('input').forEach(i=>i.oninput=()=>{root.querySelector('#'+i.id+'-v').textContent=i.value;update()});update();}
function paint(root,img,stats){root.querySelector('.viz-stage').innerHTML=img;root.querySelector('.viz-stats').innerHTML=stats;}
Object.assign(VISUALS,{
sets:{name:'Estados, conjuntos y condiciones',world:'foundations',question:'¿Cómo se construye un espacio de estados?',mount(root){mount(root,body(`${range('sa','A · posiciones ≤',1,3,2,1)}${range('sb','B · orientación',0,1,1,1)}`,'Un estado es el par (posición,orientación). Hay 3×2 estados. A limita la posición; B elige orientación 0 o 1. Verde=A∩B; azul=solo A; naranja=solo B. Los puntos son estados, no probabilidades.'),()=>{const a=+root.querySelector('#sa').value,b=+root.querySelector('#sb').value;let pic='';for(let x=1;x<=3;x++)for(let y=0;y<=1;y++){const inA=x<=a,inB=y===b,c=inA&&inB?C.g:inA?C.c:inB?C.o:C.m;pic+=`<rect x="${55+(x-1)*175}" y="${45+y*120}" width="140" height="85" fill="${c}14" stroke="${c}"/><text x="${125+(x-1)*175}" y="${95+y*120}" text-anchor="middle" fill="${c}" font-size="23">(${x},${y})</text>`;}paint(root,svg(pic,'Producto cartesiano de posición y orientación'),stat('|X×Y|','6')+stat('|A|',a*2,C.c)+stat('|B|','3',C.o)+stat('|A∩B|',a,C.g));});}},
sums:{name:'De suma finita a normalización',world:'foundations',question:'¿Por qué sumar los pesos vuelve coherente una distribución?',mount(root){mount(root,body(`${range('sn','n · estados',2,12,5,1)}${range('sr','r · razón geométrica',.1,.95,.6,.05)}`,'Pesos wᵢ=rⁱ para i=0,…,n−1. Z=∑wᵢ=(1−rⁿ)/(1−r); pᵢ=wᵢ/Z. Sumar y dividir por Z produce probabilidades que suman 1. Si n→∞ y |r|<1, Z→1/(1−r).'),()=>{const n=+root.querySelector('#sn').value,r=+root.querySelector('#sr').value,Z=(1-r**n)/(1-r),w=480/n;let pic='<path d="M60 250H555" stroke="#4b606f"/>';for(let i=0;i<n;i++){const p=r**i/Z,h=p*300;pic+=`<rect x="${65+i*w}" y="${250-h}" width="${w*.72}" height="${h}" fill="${i===0?C.g:C.c}"/><text x="${65+i*w+w*.36}" y="275" fill="${C.m}" text-anchor="middle" font-size="12">${i}</text>`;}paint(root,svg(pic,'Pesos geométricos normalizados'),stat('Z',fmt(Z),C.o)+stat('p₀',fmt(1/Z),C.g)+stat('Σpᵢ','1.000'));});}},
trig:{name:'Rotación y proyecciones',world:'foundations',question:'¿De dónde salen seno y coseno?',mount(root){mount(root,body(`${range('ta','θ · grados',0,360,45,1)}`,'El punto sobre el círculo unitario es (cos θ,sin θ). Los radianes son longitud de arco/radio; 180°=π rad. La identidad cos²+sin²=1 conserva la norma bajo rotación.'),()=>{const deg=+root.querySelector('#ta').value,t=deg*Math.PI/180,x=Math.cos(t),y=Math.sin(t),px=300+110*x,py=150-110*y;const pic=`<path d="M130 150H470M300 20V280" stroke="#405462"/><circle cx="300" cy="150" r="110" fill="none" stroke="#3b5865"/><path d="M300 150L${px} ${py}" stroke="${C.g}" stroke-width="2.5"/><path d="M300 150H${px}" stroke="${C.c}" stroke-width="3"/><path d="M${px} 150V${py}" stroke="${C.o}" stroke-width="3"/><circle cx="${px}" cy="${py}" r="5" fill="${C.g}"/><text x="470" y="175" fill="${C.c}" font-size="14">cos θ</text><text x="325" y="26" fill="${C.o}" font-size="14">sin θ</text>`;paint(root,svg(pic,'Círculo unitario y proyecciones trigonométricas'),stat('RADIANES',fmt(t),C.g)+stat('cos θ',fmt(x),C.c)+stat('sin θ',fmt(y),C.o)+stat('NORMA²','1.000'));});}},
limits:{name:'Un límite en un agujero',world:'foundations',question:'¿Puede existir un límite donde la función no existe?',mount(root){mount(root,body(`${range('lh','h · proximidad',.001,1,.5,.001)}`,'f(x)=(x²−1)/(x−1) coincide con x+1 para x≠1. La función original no está definida en x=1; su límite sí es 2. Acércate por ambos lados y conserva la distinción entre valor y límite.'),()=>{const h=+root.querySelector('#lh').value,X=x=>70+x*200,Y=y=>260-y*70;paint(root,svg(`<path d="M70 260H560M70 20V260" stroke="#4b606f"/><path d="M${X(0)} ${Y(1)}L${X(2)} ${Y(3)}" stroke="${C.c}" stroke-width="2.5"/><circle cx="${X(1)}" cy="${Y(2)}" r="7" fill="#0b1014" stroke="${C.g}" stroke-width="2"/><circle cx="${X(1-h)}" cy="${Y(2-h)}" r="5" fill="${C.o}"/><circle cx="${X(1+h)}" cy="${Y(2+h)}" r="5" fill="${C.o}"/><text x="${X(1)+16}" y="${Y(2)-15}" fill="${C.g}" font-size="15">límite 2 · f(1) no definida</text>`, 'Límite bilateral en una discontinuidad removible'),stat('f(1−h)',fmt(2-h),C.o)+stat('f(1+h)',fmt(2+h),C.o)+stat('LÍMITE','2.000',C.g));});}},
convolution:{name:'Sumar incertidumbres',world:'probability',question:'¿Cómo se distribuye la suma de dos variables?',mount(root){mount(root,body(`${range('cp','p · X∼Bernoulli(p)',.01,.99,.4,.01)}${range('cq','q · Y∼Bernoulli(q)',.01,.99,.7,.01)}`,'X e Y son independientes. Para Z=X+Y, p_Z(z)=∑ₓp_X(x)p_Y(z−x). Las dos formas de obtener 1 se suman. Si hay dependencia, esta convolución de marginales no basta.'),()=>{const p=+root.querySelector('#cp').value,q=+root.querySelector('#cq').value,probs=[(1-p)*(1-q),p*(1-q)+(1-p)*q,p*q];let pic='<path d="M50 250H560" stroke="#4b606f"/>';probs.forEach((v,i)=>pic+=`<rect x="${100+i*160}" y="${250-v*200}" width="85" height="${v*200}" fill="${i===1?C.g:C.c}"/><text x="${142+i*160}" y="275" text-anchor="middle" fill="${C.m}" font-size="14">Z=${i}</text><text x="${142+i*160}" y="${235-v*200}" text-anchor="middle" fill="${C.c}" font-size="15">${fmt(v)}</text>`);paint(root,svg(pic,'Distribución de la suma de dos Bernoulli independientes'),stat('E[Z]',fmt(p+q),C.g)+stat('VAR[Z]',fmt(p*(1-p)+q*(1-q)),C.o)+stat('Σ p_Z','1.000'));});}},
clt:{name:'El límite central emerge',world:'statistics',question:'¿Por qué aparece una campana al sumar?',mount(root){mount(root,body(`${range('cn','n · Bernoulli sumadas',2,70,10,1)}${range('ct','p · éxito',.1,.9,.5,.05)}`,'Sₙ suma n Bernoulli iid. Visualizamos (Sₙ−np)/√(np(1−p)); las barras muestran masa/anchura, comparables a una densidad. La normal azul es una aproximación asintótica, especialmente buena lejos de p=0 o 1.'),()=>{const n=+root.querySelector('#cn').value,p=+root.querySelector('#ct').value,s=Math.sqrt(n*p*(1-p)),X=z=>300+z*62,Y=v=>250-v*450;let prob=(1-p)**n,pic='<path d="M40 250H560" stroke="#4b606f"/>';for(let k=0;k<=n;k++){if(k>0)prob*=((n-k+1)/k)*(p/(1-p));const z=(k-n*p)/s,height=prob*s;if(z>-4.1&&z<4.1)pic+=`<rect x="${X(z)-30/s}" y="${Y(height)}" width="${60/s}" height="${height*450}" fill="#c7f36b55" stroke="${C.g}" stroke-width=".5"/>`;}let d='';for(let z=-4;z<=4;z+=.04)d+=`${d?'L':'M'}${X(z)} ${Y(MATH_ENGINE.gauss(z,0,1))}`;pic+=`<path d="${d}" fill="none" stroke="${C.c}" stroke-width="2.5"/>`;paint(root,svg(pic,'Suma binomial estandarizada y normal estándar'),stat('E[Sₙ]',fmt(n*p),C.o)+stat('VAR[Sₙ]',fmt(n*p*(1-p)),C.g)+stat('ASIMETRÍA',fmt((1-2*p)/s)));});}},
maxent:{name:'Restricciones y máxima entropía',world:'information',question:'¿Cómo emerge una distribución desde una restricción?',mount(root){mount(root,body(`${range('ml','λ · multiplicador',-2,2,.5,.05)}`,'Cinco estados tienen energías x=0,…,4. Maximizar H bajo media y normalización da p(x)∝exp(−λx). λ=0 recupera uniformidad; λ>0 favorece estados bajos. La media determina λ, no una preferencia arbitraria posterior.'),()=>{const l=+root.querySelector('#ml').value,weights=[0,1,2,3,4].map(x=>Math.exp(-l*x)),Z=weights.reduce((a,b)=>a+b,0),p=weights.map(w=>w/Z),mean=p.reduce((a,v,i)=>a+v*i,0),h=-p.reduce((a,v)=>a+v*Math.log(v),0);let pic='<path d="M40 250H560" stroke="#4b606f"/>';p.forEach((v,i)=>pic+=`<rect x="${80+i*95}" y="${250-v*220}" width="60" height="${v*220}" fill="${C.c}"/><text x="${110+i*95}" y="278" text-anchor="middle" fill="${C.m}" font-size="14">${i}</text>`);paint(root,svg(pic,'Distribución de máxima entropía sobre cinco estados'),stat('MEDIA',fmt(mean),C.g)+stat('ENTROPÍA',fmt(h))+stat('Z',fmt(Z),C.o));});}}
});
const val=(r,id)=>+r.querySelector('#'+id).value;
Object.assign(FIELD_MISSIONS,{
sets:{title:'Combina dos condiciones',goal:'Elige A con cuatro estados y B orientación 0. La intersección debe tener dos estados.',clue:'A permite dos de las tres posiciones y ambas orientaciones.',test(r){return{pass:val(r,'sa')===2&&val(r,'sb')===0,readout:`|A∩B|=${val(r,'sa')}`}}},
sums:{title:'Normaliza un sistema',goal:'Con cinco estados, consigue p₀ entre 0.51 y 0.52.',clue:'Prueba una razón de 1/2. Z es la suma de una progresión geométrica finita.',test(r){const n=val(r,'sn'),p0=(1-val(r,'sr'))/(1-val(r,'sr')**n);return{pass:n===5&&p0>.51&&p0<.52,readout:`p₀=${fmt(p0)}`}}},
trig:{title:'Rota sin cambiar la norma',goal:'Haz una rotación de π/2 radianes: e₁ debe terminar en e₂.',clue:'π radianes son 180 grados.',test(r){const d=val(r,'ta');return{pass:d===90,readout:`θ=${fmt(d*Math.PI/180)} rad`}}},
limits:{title:'Acércate desde ambos lados',goal:'Consigue que ambos valores estén a menos de 0.01 del límite, sin evaluar f(1).',clue:'La distancia al límite es h.',test(r){return{pass:val(r,'lh')<.01,readout:`Error bilateral=${fmt(val(r,'lh'))}`}}},
convolution:{title:'Dos caminos al mismo resultado',goal:'Con dos Bernoulli de p=q=0.5, haz que la suma tenga masas (0.25,0.5,0.25).',clue:'Z=1 ocurre por (1,0) o (0,1).',test(r){const p=val(r,'cp'),q=val(r,'cq');return{pass:Math.abs(p-.5)<.001&&Math.abs(q-.5)<.001,readout:`P(Z=1)=${fmt(p+q-2*p*q)}`}}},
clt:{title:'Domina la estandarización',goal:'Configura una suma con media 20 y varianza 10.',clue:'np=20 y np(1−p)=10 → resuelve primero p.',test(r){const n=val(r,'cn'),p=val(r,'ct');return{pass:Math.abs(n*p-20)<.001&&Math.abs(n*p*(1-p)-10)<.001,readout:`Media=${fmt(n*p)} · var=${fmt(n*p*(1-p))}`}}},
maxent:{title:'Elimina el compromiso extra',goal:'Quita la restricción de media desigual: logra uniformidad y H=ln 5.',clue:'Cuando λ=0 todos los pesos son iguales.',test(r){const l=val(r,'ml');return{pass:Math.abs(l)<.001,readout:`λ=${l} · máximo H=${fmt(Math.log(5))}`}}}
});
})();
